import com.chance.bitlifediag.*;
import com.github.bhlangonijr.chesslib.*;
import com.github.bhlangonijr.chesslib.move.Move;
import java.util.*;
public class MilitaryModelTest {
 static int checks;static void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static MilitaryModel.Person p(int y,int age,int sex,String c,boolean serving){return new MilitaryModel.Person(y,age,sex,80,70,c,"London",serving,true);}
 static MilitaryModel.State s(String country){MilitaryModel.State s=new MilitaryModel.State("");s.put("jurisdiction",country);return s;}
 static long perft(Board b,int depth){if(depth==0)return 1;long n=0;for(Move m:b.legalMoves()){check(b.doMove(m,true),"legal move applies");n+=perft(b,depth-1);b.undoMove();}return n;}
 static ChessGame position(String fen){MilitaryModel.State s=new MilitaryModel.State("");s.put("origin",fen);s.put("opponentId","test");s.put("opponent","Test opponent");return new ChessGame(s.encode(),"test","Test opponent");}
 static void play(ChessGame g,String move){g.move(new Move(move,g.board.getSideToMove()));}
 public static void main(String[]args){
  MilitaryModel.State timeline=s("United Kingdom");MilitaryModel.advance(timeline,p(1913,20,0,"United Kingdom",false));List<MilitaryModel.Event> news=MilitaryModel.advance(timeline,p(1914,21,0,"United Kingdom",false));check(news.size()==1&&news.get(0).date==19140728,"WWI start");check(MilitaryModel.advance(new MilitaryModel.State(timeline.encode()),p(1914,21,0,"United Kingdom",false)).isEmpty(),"news not replayed on reload");
  news=MilitaryModel.advance(timeline,p(1918,25,0,"United Kingdom",false));check(news.size()==2&&news.get(0).date==19170406&&news.get(1).ending,"skipped years chronological and armistice closes missions");
  MilitaryModel.advance(timeline,p(1938,45,0,"United Kingdom",false));news=MilitaryModel.advance(timeline,p(1946,53,0,"United Kingdom",false));check(news.size()==5,"all WWII start, entry and ending anchors crossed");check(news.get(2).date==19450508&&news.get(3).date==19450815&&news.get(4).date==19450902,"VE day separated from Pacific and formal surrender");check(MilitaryModel.war(1945)==0&&MilitaryModel.theme(1945)==4,"annual year-end world state is postwar");check(MilitaryModel.war(2026)==0,"no war in modern infancy");
  check(!MilitaryModel.eligibility(p(1915,25,0,"United Kingdom",false),s("United Kingdom")).draft,"UK no conscription before 1916");check(MilitaryModel.eligibility(p(1916,25,0,"United Kingdom",false),s("United Kingdom")).draft,"UK 1916 main cohort");
  check(!MilitaryModel.eligibility(p(1917,20,0,"United States",false),s("United States")).draft,"US initial cohort lower bound");check(MilitaryModel.eligibility(p(1917,21,0,"United States",false),s("United States")).draft,"US 1917 age21");check(!MilitaryModel.eligibility(p(1939,25,0,"United States",false),s("United States")).draft,"US before 1940 law");check(MilitaryModel.eligibility(p(1940,25,0,"United States",false),s("United States")).draft&&!MilitaryModel.involved(1940,"United States"),"pre-entry registration distinct from deployment");
  MilitaryModel.Eligibility au=MilitaryModel.eligibility(p(1915,25,0,"Australia",false),s("Australia"));check(!au.draft&&au.volunteer,"Australia WWI AIF voluntary overseas");check(!MilitaryModel.eligibility(p(1940,25,1,"United Kingdom",false),s("United Kingdom")).draft,"native female birth-sex is1, male0");check(!MilitaryModel.eligibility(p(1940,17,0,"United Kingdom",false),s("United Kingdom")).volunteer,"no child recruitment");check(!MilitaryModel.eligibility(p(1940,25,0,"Switzerland",false),s("Switzerland")).supported,"unsupported law honestly unavailable");check(!MilitaryModel.eligibility(p(1940,25,0,"United Kingdom",false),s("United States")).draft,"residence cannot establish jurisdiction");
  MilitaryModel.State service=s("United Kingdom");MilitaryModel.advance(service,p(1939,22,0,"United Kingdom",false));MilitaryModel.register(service,p(1939,22,0,"United Kingdom",false),false);check(service.i("stage",0)==1,"registration keeps civilian state");MilitaryModel.advance(service,p(1940,23,0,"United Kingdom",false));check(service.i("stage",0)==2,"annual call-up");MilitaryModel.assess(service,p(1940,23,0,"United Kingdom",false));check(service.i("stage",0)==3,"assessment separate");MilitaryModel.inducted(service,p(1940,23,0,"United Kingdom",false));check(service.i("stage",0)==5&&service.i("missions",0)==0,"induction not instant deployment");
  try{MilitaryModel.assign(service,p(1940,23,0,"United Kingdom",true),"Aircrew");throw new AssertionError("instant pilot");}catch(IllegalStateException expected){checks++;}
  MilitaryModel.newYear(service,1940);MilitaryModel.train(service,"Aircrew");MilitaryModel.train(service,"Aircrew");MilitaryModel.advance(service,p(1941,24,0,"United Kingdom",true));MilitaryModel.assign(service,p(1941,24,0,"United Kingdom",true),"Aircrew");check(service.i("stage",0)==7,"trained aircrew assignment");MilitaryModel.begin(service,p(1941,24,0,"United Kingdom",true),"flight");MilitaryModel.decide(service,p(1941,24,0,"United Kingdom",true),0);String encoded=service.encode();MilitaryModel.State resumed=new MilitaryModel.State(encoded);check(resumed.i("phase",0)==1,"mission resumes same decision");MilitaryModel.begin(resumed,p(1941,24,0,"United Kingdom",true),"flight");check(resumed.i("phase",0)==1,"reopen cannot restart operation");MilitaryModel.decide(resumed,p(1941,24,0,"United Kingdom",true),0);MilitaryModel.decide(resumed,p(1941,24,0,"United Kingdom",true),1);check(resumed.i("missions",0)==1&&resumed.s("mission").isEmpty(),"completed result settles once");try{MilitaryModel.decide(resumed,p(1941,24,0,"United Kingdom",true),0);throw new AssertionError("duplicate result");}catch(IllegalStateException expected){checks++;}
  MilitaryModel.advance(resumed,p(1945,28,0,"United Kingdom",true));check(resumed.i("stage",0)==8&&resumed.i("equipped",1)==0,"postwar clears combat and layers, preserves service");check(resumed.i("missions",0)==1,"medal/tour record persists");
  MilitaryModel.State moved=s("United States");moved.put("obligation","United Kingdom");check(!MilitaryModel.eligibility(p(1942,25,0,"United States",false),moved).draft,"migration does not erase existing obligation");MilitaryModel.State nativeService=s("Australia");MilitaryModel.advance(nativeService,p(1942,25,0,"Australia",true));check(nativeService.i("stage",0)==5,"existing native military post adopted without duplicate enlistment");
  Board b=new Board();check(perft(b,3)==8902,"start position perft3");b.loadFromFen("r3k2r/p1ppqpb1/bn2pnp1/3PN3/1p2P3/2N2Q1p/PPPBBPPP/R3K2R w KQkq - 0 1");check(perft(b,2)==2039,"Kiwipete castling and attack perft2");
  ChessGame ep=position("4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1");play(ep,"e5d6");check(ep.board.getPiece(Square.D5)==Piece.NONE,"en passant removes captured pawn");ChessGame pinned=position("k3r3/8/8/3pP3/8/8/8/4K3 w - d6 0 1");check(!pinned.board.legalMoves().contains(new Move("e5d6",Side.WHITE)),"en passant cannot expose king");
  ChessGame castle=position("r3k2r/8/8/8/8/8/8/R3K2R w KQkq - 0 1");play(castle,"e1g1");check(castle.board.getPiece(Square.F1)==Piece.WHITE_ROOK&&castle.board.getPiece(Square.H1)==Piece.NONE,"castling moves rook");
  ChessGame promotion=position("4k3/P7/8/8/8/8/8/4K3 w - - 0 1");int promotions=0;for(Move m:promotion.board.legalMoves())if(m.getFrom()==Square.A7&&m.getTo()==Square.A8)promotions++;check(promotions==4,"four promotion choices");play(promotion,"a7a8n");check(promotion.board.getPiece(Square.A8)==Piece.WHITE_KNIGHT,"underpromotion");
  ChessGame mate=new ChessGame("","test","Test opponent");for(String m:new String[]{"f2f3","e7e5","g2g4","d8h4"})play(mate,m);check(mate.board.isMated()&&mate.ended(),"checkmate detected");check(mate.settle()&&!mate.settle(),"chess reward once");ChessGame stale=position("7k/5Q2/6K1/8/8/8/8/8 b - - 0 1");check(stale.board.isStaleMate()&&!stale.board.isMated(),"stalemate");
  ChessGame repetition=new ChessGame("","test","Test opponent");for(String m:new String[]{"g1f3","g8f6","f3g1","f6g8","g1f3","g8f6","f3g1","f6g8"})play(repetition,m);ChessGame restored=new ChessGame(repetition.save(),"test","Test opponent");check(restored.board.isRepetition()&&restored.ended(),"repetition survives save and reload");ChessGame fifty=position("4k3/8/8/8/8/8/8/R3K3 w - - 99 60");play(fifty,"a1a2");check(fifty.board.getHalfMoveCounter()==100&&fifty.ended(),"fifty-move draw");
  ChessGame other=new ChessGame("","first","First parent");play(other,"e2e4");try{new ChessGame(other.save(),"second","Second parent");throw new AssertionError("opponent replaced");}catch(IllegalStateException expected){checks++;}
  for(int level=1;level<=3;level++){ChessGame ai=new ChessGame("","test","Test opponent");Move chosen=ai.choose(level,System.nanoTime()+100000000);check(ai.board.legalMoves().contains(chosen),"AI returns legal move level "+level);check(ai.board.getFen().equals(new Board().getFen()),"search never changes live board");}
  System.out.println("{\"passed\":true,\"checks\":"+checks+",\"native_birth_sex_enum_verified\":true,\"perft_start_depth3\":8902,\"perft_kiwipete_depth2\":2039,\"host_JVM\":true,\"Android_UI_tested\":false}");
 }
}
